// FLEMutationHook returns an ent.Hook that computes blind indexes and encrypts fields
// before database persistence in a 100% type-safe manner without reflection.
func FLEMutationHook(hasher crypto.Hasher, defaultEnc crypto.Encryptor, patientResolvers ...fle.PatientEncryptorResolver) Hook {
	var patientResolver fle.PatientEncryptorResolver
	if len(patientResolvers) > 0 {
		patientResolver = patientResolvers[0]
	}
	return func(next Mutator) Mutator {
		return MutateFunc(func(ctx context.Context, m Mutation) (Value, error) {
			if !m.Op().Is(OpCreate | OpUpdate | OpUpdateOne) {
				return next.Mutate(ctx, m)
			}
			enc, err := fle.ResolveEncryptor(ctx, defaultEnc)
			if err != nil {
				return nil, err
			}
			h := fle.ResolveHasher(ctx, hasher)

			switch mut := m.(type) {
			case *AppointmentMutation:
				if err := encryptAppointmentMutation(ctx, h, enc, mut, patientResolver); err != nil {
					return nil, err
				}
			case *EpisodeMutation:
				if err := encryptEpisodeMutation(ctx, h, enc, mut, patientResolver); err != nil {
					return nil, err
				}
			case *FindingMutation:
				if err := encryptFindingMutation(ctx, h, enc, mut, patientResolver); err != nil {
					return nil, err
				}
			case *PatientMutation:
				if err := encryptPatientMutation(ctx, h, enc, mut, patientResolver); err != nil {
					return nil, err
				}
			case *PlanItemMutation:
				if err := encryptPlanItemMutation(ctx, h, enc, mut, patientResolver); err != nil {
					return nil, err
				}
			case *ProblemMutation:
				if err := encryptProblemMutation(ctx, h, enc, mut, patientResolver); err != nil {
					return nil, err
				}
			}

			val, err := next.Mutate(ctx, m)
			if err != nil {
				return nil, err
			}

			if val != nil {
				switch v := val.(type) {
				case *Appointment:
					if err := DecryptAppointment(ctx, enc, v, patientResolver); err != nil {
						return nil, err
					}
				case *Episode:
					if err := DecryptEpisode(ctx, enc, v, patientResolver); err != nil {
						return nil, err
					}
				case *Finding:
					if err := DecryptFinding(ctx, enc, v, patientResolver); err != nil {
						return nil, err
					}
				case *Patient:
					if err := DecryptPatient(ctx, enc, v, patientResolver); err != nil {
						return nil, err
					}
				case *PlanItem:
					if err := DecryptPlanItem(ctx, enc, v, patientResolver); err != nil {
						return nil, err
					}
				case *Problem:
					if err := DecryptProblem(ctx, enc, v, patientResolver); err != nil {
						return nil, err
					}
				}
			}

			return val, nil
		})
	}
}

// FLEDecryptionInterceptor returns an ent.Interceptor that transparently decrypts
// all queried entities in a 100% type-safe manner without reflection.
func FLEDecryptionInterceptor(defaultEnc crypto.Encryptor, patientResolvers ...fle.PatientEncryptorResolver) Interceptor {
	var patientResolver fle.PatientEncryptorResolver
	if len(patientResolvers) > 0 {
		patientResolver = patientResolvers[0]
	}
	return InterceptFunc(func(next Querier) Querier {
		return QuerierFunc(func(ctx context.Context, q Query) (Value, error) {
			val, err := next.Query(ctx, q)
			if err != nil {
				return nil, err
			}
			enc, err := fle.ResolveEncryptor(ctx, defaultEnc)
			if err != nil || val == nil {
				return val, err
			}

			switch v := val.(type) {
			case *Appointment:
				if err := DecryptAppointment(ctx, enc, v, patientResolver); err != nil {
					return nil, err
				}
			case []*Appointment:
				for _, item := range v {
					if err := DecryptAppointment(ctx, enc, item, patientResolver); err != nil {
						return nil, err
					}
				}
			case *Episode:
				if err := DecryptEpisode(ctx, enc, v, patientResolver); err != nil {
					return nil, err
				}
			case []*Episode:
				for _, item := range v {
					if err := DecryptEpisode(ctx, enc, item, patientResolver); err != nil {
						return nil, err
					}
				}
			case *Finding:
				if err := DecryptFinding(ctx, enc, v, patientResolver); err != nil {
					return nil, err
				}
			case []*Finding:
				for _, item := range v {
					if err := DecryptFinding(ctx, enc, item, patientResolver); err != nil {
						return nil, err
					}
				}
			case *Patient:
				if err := DecryptPatient(ctx, enc, v, patientResolver); err != nil {
					return nil, err
				}
			case []*Patient:
				for _, item := range v {
					if err := DecryptPatient(ctx, enc, item, patientResolver); err != nil {
						return nil, err
					}
				}
			case *PlanItem:
				if err := DecryptPlanItem(ctx, enc, v, patientResolver); err != nil {
					return nil, err
				}
			case []*PlanItem:
				for _, item := range v {
					if err := DecryptPlanItem(ctx, enc, item, patientResolver); err != nil {
						return nil, err
					}
				}
			case *Problem:
				if err := DecryptProblem(ctx, enc, v, patientResolver); err != nil {
					return nil, err
				}
			case []*Problem:
				for _, item := range v {
					if err := DecryptProblem(ctx, enc, item, patientResolver); err != nil {
						return nil, err
					}
				}
			}

			return val, nil
		})
	})
}
